"""Draft a structured clinical note from a transcript with a local LLM (Ollama).

Every section carries `sources`: indices of the transcript segments it was
drawn from, so a clinician can jump from any claim back to what was said.
"""

import json
import re

import httpx

from ..config import settings
from .safety import ensure_allergies

SECTIONS = ["subjective", "objective", "assessment", "plan"]

DISCLAIMER = (
    "Draft generated by software from a consultation transcript. "
    "It must be reviewed and approved by the treating clinician."
)

SYSTEM_PROMPT = (
    "You are a documentation assistant drafting a SOAP note from a doctor-patient "
    "consultation transcript. Rules: use ONLY information stated in the transcript; "
    "if a section was not discussed write exactly 'Not discussed'; never diagnose, "
    "infer, or add advice the clinician did not give; keep each section concise. "
    "Respond with JSON only."
)

# Empty values on purpose: placeholder text in the example gets copied into the
# note by smaller models, so the section guidance lives in prose instead.
SCHEMA_HINT = {
    **{name: {"text": "", "sources": []} for name in SECTIONS},
    "allergies": [{"text": "", "sources": []}],
    "medications": [{"text": "", "sources": []}],
    "action_items": [{"text": "", "sources": []}],
}

SECTION_GUIDE = (
    "subjective: what the patient reports (symptoms, duration, history).\n"
    "objective: what the clinician measured or observed (vitals, examination, results).\n"
    "assessment: the clinician's stated impression or diagnosis.\n"
    "plan: treatment, prescriptions, advice and follow-up the clinician gave.\n"
    "allergies: every drug, food or other allergy or adverse reaction the patient "
    "mentions, one entry each. Never leave this empty if an allergy was mentioned.\n"
    "medications: every medicine the patient says they currently take or took.\n"
    "action_items: concrete follow-up tasks for the patient or staff."
)


SPEAKER_GUIDE = (
    "Speakers are numbered, not named. The clinician is the speaker who asks about "
    "symptoms, examines and prescribes; the patient is the other. Symptoms, history, "
    "allergies and medicines the patient takes come from the patient.\n\n"
)


def build_user_prompt(segments: list[dict]) -> str:
    def line(i: int, s: dict) -> str:
        who = f"{s['speaker']}: " if s.get("speaker") else ""
        return f"[{i}] {who}{s['text']}"

    lines = "\n".join(line(i, s) for i, s in enumerate(segments))
    labelled = any(s.get("speaker") for s in segments)
    return (
        f"Section guide:\n{SECTION_GUIDE}\n\n"
        f"{SPEAKER_GUIDE if labelled else ''}"
        "Fill in the JSON below. Write each section's text as short sentences that "
        "state what was actually said, and set sources to the segment numbers in "
        "square brackets that support it. Do not repeat the section guide.\n"
        f"{json.dumps(SCHEMA_HINT)}\n\nTranscript:\n{lines}"
    )


_NOTHING_RE = re.compile(
    r"\bnone\b|\bn/?a\b|\bnot (?:mentioned|discussed|stated|specified)\b|\bnothing\b",
    re.IGNORECASE,
)


def _clean_sources(raw, n_segments: int) -> list[int]:
    if not isinstance(raw, list):
        return []
    return sorted({i for i in raw if isinstance(i, int) and 0 <= i < n_segments})


def _section(value, n_segments: int) -> dict:
    if isinstance(value, str):
        return {"text": value.strip() or "Not discussed", "sources": []}
    if isinstance(value, dict):
        text = str(value.get("text", "")).strip() or "Not discussed"
        return {"text": text, "sources": _clean_sources(value.get("sources"), n_segments)}
    return {"text": "Not discussed", "sources": []}


def parse_note(raw: str, n_segments: int) -> dict:
    """Parse the model's reply into the note shape, tolerating code fences."""
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", raw.strip())
    data = json.loads(cleaned)
    if not isinstance(data, dict):
        raise ValueError("model did not return a JSON object")

    def entries(key: str) -> list[dict]:
        raw_items = data.get(key) or []
        if not isinstance(raw_items, list):
            raw_items = [raw_items]
        out = []
        for item in raw_items:
            section = _section(item, n_segments)
            if section["text"] == "Not discussed":
                continue
            # "None mentioned" with no citation is the model filling space, not a
            # finding. A cited "No known allergies" is kept: that is a real statement.
            if not section["sources"] and _NOTHING_RE.search(section["text"]):
                continue
            out.append(section)
        return out

    return {
        "sections": {name: _section(data.get(name), n_segments) for name in SECTIONS},
        "allergies": entries("allergies"),
        "medications": entries("medications"),
        "action_items": entries("action_items"),
        "flags": [],
        "disclaimer": DISCLAIMER,
    }


async def summarize(segments: list[dict]) -> dict:
    payload = {
        "model": settings.ollama_model,
        "stream": False,
        "format": "json",
        "options": {"temperature": 0.1, "num_ctx": settings.ollama_num_ctx},
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": build_user_prompt(segments)},
        ],
    }
    url = f"{settings.ollama_url.rstrip('/')}/api/chat"
    async with httpx.AsyncClient(timeout=settings.llm_timeout_s) as client:
        resp = await client.post(url, json=payload)
    resp.raise_for_status()
    note = parse_note(resp.json()["message"]["content"], len(segments))
    return ensure_allergies(note, segments)
